// Scope: Figma "↳ Form" page (InputControl 427:2001, InputField 428:2042, Form 435:8, Examples 436:282, Documentation 1021:263).
// Generated per agents/08-storybook-agent/form-story-skill.md — stories cover only what Figma has.
// There is no Form component in code: Figma's Form is itself a composition of InputField and Button instances,
// so these stories compose TextInput, Select, Checkbox, Button and Alert the same way.
import type { CSSProperties } from 'react';
import type { Meta, StoryObj } from '@storybook/react-vite';
import { expect } from 'storybook/test';

import { Alert } from '../Alert/Alert';
import { Button } from '../Button/Button';
import { Checkbox, CheckboxGroup } from '../Checkbox/Checkbox';
import { Select } from '../Select/Select';
import { TextInput } from '../TextInput/TextInput';
import { Labelled, Matrix, stack } from '../../storybook/helpers';

const COUNTRY = [{ value: 'us', label: 'United States' }];
const formStyle: CSSProperties = { display: 'flex', flexDirection: 'column', gap: 'var(--space-stack-md)', width: 360 };
const actions: CSSProperties = { display: 'flex', gap: 'var(--space-inline-md)', justifyContent: 'flex-end' };

type FormState = 'Default' | 'Submitting' | 'Success' | 'Error' | 'Disabled';

/** Figma "Form" (435:8): section heading, InputField rows, a checkbox, Cancel / Submit, and page-level submission states. */
function PersonalInformation({ state }: { state: FormState }) {
  const disabled = state === 'Disabled';
  return (
    <form style={formStyle} aria-label={`Personal information, ${state}`} onSubmit={(e) => e.preventDefault()}>
      {state === 'Success' && <Alert sentiment="success" title="Form submitted" description="Thank you, we received your information." />}
      {state === 'Error' && <Alert sentiment="danger" title="Submission failed" description="Please fix the errors below and try again." />}
      <h3 className="text-heading-sm" style={{ margin: 0 }}>Personal information</h3>
      <TextInput label="Full name" required defaultValue="Jordan Lee" disabled={disabled} />
      <TextInput
        label="Email address"
        required
        placeholder="Enter your email"
        defaultValue={state === 'Error' ? 'jordan@company.com' : undefined}
        error={state === 'Error' ? 'Enter a valid email address' : undefined}
        disabled={disabled}
      />
      <Select label="Country" options={COUNTRY} defaultValue="us" disabled={disabled} />
      <CheckboxGroup legend="Label">
        <Checkbox label="I agree to the terms and conditions" disabled={disabled} />
      </CheckboxGroup>
      <div style={actions}>
        <Button variant="secondary" disabled={disabled || state === 'Submitting'}>Cancel</Button>
        <Button type="submit" disabled={disabled || state === 'Submitting'}>{state === 'Submitting' ? 'Submitting...' : 'Submit'}</Button>
      </div>
    </form>
  );
}

